const moonTooltip=document.querySelector("#moonTooltip");function moonHit(x,y){let best=null,dist=18;moonScreenPositions.forEach(item=>{let p=item.screen;if(p[2]<=0)return;let d=Math.hypot(x-p[0],y-p[1]);if(d<dist){best=item;dist=d}});return best}function showMoonTooltip(x,y){let hit=moonHit(x,y);if(!hit){moonTooltip.hidden=true;canvas.style.cursor=state.drag?"grabbing":"grab";return null}moonTooltip.hidden=false;moonTooltip.style.left=x+"px";moonTooltip.style.top=y+"px";moonTooltip.querySelector("span").textContent=bodies[hit.parent].name.toUpperCase()+" · MOND";moonTooltip.querySelector("strong").textContent=hit.moon.name;canvas.style.cursor="pointer";return hit}let touchDistance=0,touchZoom=0;canvas.addEventListener('pointerdown',e=>{state.drag=true;state.lastX=e.clientX;state.lastY=e.clientY;state.downX=e.clientX;state.downY=e.clientY;moonTooltip.hidden=true;canvas.style.cursor="grabbing";canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(e.pointerType==='touch'&&touchDistance)return;if(!state.drag){showMoonTooltip(e.clientX,e.clientY);return}state.yaw-=(e.clientX-state.lastX)*.006;state.pitch=Math.max(-1.35,Math.min(1.48,state.pitch+(e.clientY-state.lastY)*.006));state.lastX=e.clientX;state.lastY=e.clientY});canvas.addEventListener("pointerup",e=>{let wasClick=Math.hypot(e.clientX-state.downX,e.clientY-state.downY)<4;state.drag=false;if(wasClick){let hit=moonHit(e.clientX,e.clientY),cosmic=hit?null:cosmicHit(e.clientX,e.clientY);if(hit){select(hit.parent);selectMoon(hit.moon)}else if(cosmic){selectCosmic(cosmic.data)}else{let best=-1,dist=22;screenPositions.forEach((p,i)=>{let d=Math.hypot(e.clientX-p[0],e.clientY-p[1]);if(d<dist){best=i;dist=d}});if(best>=0)select(best)}}showMoonTooltip(e.clientX,e.clientY)});canvas.addEventListener("pointerleave",()=>{moonTooltip.hidden=true;canvas.style.cursor="grab"});canvas.addEventListener('touchstart',e=>{if(e.touches.length===2){touchDistance=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);touchZoom=state.zoom}},{passive:true});canvas.addEventListener('touchmove',e=>{if(e.touches.length===2&&touchDistance){e.preventDefault();let d=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);state.zoom=Math.max(.08,Math.min(maxZoom(),touchZoom*touchDistance/Math.max(d,1)));constrainCosmicTarget(state.zoom);syncRegionFromZoom()}},{passive:false});canvas.addEventListener('touchend',()=>{touchDistance=0},{passive:true});canvas.addEventListener("wheel",e=>{e.preventDefault();zoomAtPointer(Math.max(.08,Math.min(maxZoom(),state.zoom*Math.exp(e.deltaY*.001))),e.clientX,e.clientY)},{passive:false});window.addEventListener('keydown',e=>{if(e.key===' '){e.preventDefault();document.querySelector('#playButton').click()}if(e.key==='Escape')document.body.classList.remove('explore');if(e.key==='ArrowLeft')state.yaw-=.08;if(e.key==='ArrowRight')state.yaw+=.08});
